package dev.tacticalcombat.client.ui;
import com.google.gson.*;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.TextFieldWidget;
import net.minecraft.text.Text;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;
/** Illustrated owner-only library. Search is explicitly page-scoped; controls share a scrollable viewport. */
public final class LibraryScreen extends ManagementScreen {
 private int page;private boolean more,canCreate=true;private List<JsonObject> records=List.of();private RpgButton refreshButton;private CharacterCanvas pane;private TextFieldWidget searchInput;private String selected="";private final List<RpgButton> actions=new ArrayList<>();
 public LibraryScreen(Screen parent){super("My Characters",parent);}
 @Override protected int maximumWidth(){return 900;}
 @Override protected void searchControls(){refreshButton=button("Refresh","",frame.x()+frame.width()-86,frame.y()+8,74,20,this::refresh).hint("Reload your personal characters; an updated server connection is required");}
 @Override protected void controls(){remove(list);if(searchInput==null){searchInput=new TextFieldWidget(textRenderer,0,0,100,20,Text.literal("Search this page"));searchInput.setMaxLength(80);searchInput.setText(query);searchInput.setPlaceholder(Text.literal("Search names, race or class on this page…"));searchInput.setChangedListener(v->{query=v;build();});}build();}
 @Override protected void filter(){}
 @Override protected void refresh(){if(busy)return;fresh=false;read(LIBRARY_LIST,args("page",page),data->{var rows=new ArrayList<JsonObject>();for(var e:array(data,"characters"))rows.add(e.getAsJsonObject().deepCopy());records=List.copyOf(rows);more=data.has("hasMore")?flag(data,"hasMore"):records.size()==8;canCreate=!data.has("canCreate")||flag(data,"canCreate");build();message="Personal characters · campaign copies stay independent.";});}
 private void build(){if(frame==null)return;int offset=pane==null?0:pane.position();String focus=pane==null?"":pane.focusedKey();if(pane!=null)remove(pane);pane=addDrawableChild(new CharacterCanvas(PlayerUiLayout.viewport(frame)));actions.clear();int w=pane.getWidth()-12,x=6;var create=add("create",new RpgButton(x,6,w,32,"Create Character","",()->{if(fresh&&!busy)client.setScreen(new LibraryCreateScreen(this));}).primary(true).wrappedTitle().hint("Start a new personal character draft"));create.active=fresh&&!busy&&canCreate;if(!canCreate)create.hint("Your personal library has reached its character limit. Delete a personal character to make room.");searchInput.setDimensionsAndPosition(w,20,x,46);pane.control("search",searchInput);pane.label("Page "+(page+1)+" · Search this page",x,73,w,RpgTheme.MUTED);int columns=PlayerUiLayout.libraryColumns(pane.getWidth()),cw=(w-(columns-1)*10)/columns,y=95,index=0,rowHeight=0;var shown=records.stream().filter(d->PlayerUiModel.matches(d,query)).toList();
  if(shown.isEmpty()){pane.panel(records.isEmpty()?"Your next adventure starts here":"No matches on this page",x,y,w,86);pane.wrapped(!fresh?"Connect to an updated Cubetable server and Refresh.":records.isEmpty()?(page==0?"Create your first personal character above. Campaign copies stay separate.":"No characters on this page. Use Previous to return to earlier characters."):"Try a different name, race or class, or browse another page.",x+10,y+29,w-20,RpgTheme.MUTED);y+=98;}
  for(var d:shown){int cx=x+index%columns*(cw+10);int nameLines=textRenderer.wrapLines(Text.literal(text(d,"name")).formatted(net.minecraft.util.Formatting.BOLD),Math.max(1,cw-66)).size(),metaLines=textRenderer.wrapLines(Text.literal(PlayerUiModel.raceLabel(PlayerUiModel.race(d))+" · "+PlayerUiModel.clazz(d)),Math.max(1,cw-20)).size(),ah=PlayerUiLayout.actionHeight(cw),height=PlayerUiLayout.characterCard(cw,nameLines,metaLines).height();if(index%columns==0)rowHeight=0;rowHeight=Math.max(rowHeight,height);pane.panel("",cx,y,cw,height);pane.icon(PlayerUiModel.icon(d),cx+10,y+12,32);int ny=y+12;for(var line:textRenderer.getTextHandler().wrapLines(text(d,"name"),Math.max(1,cw-66),net.minecraft.text.Style.EMPTY.withBold(true))){pane.boldLabel(line.getString(),cx+54,ny,cw-64,RpgTheme.GOLD);ny+=11;}pane.label(PlayerUiModel.statusLine(d),cx+54,ny+3,cw-64,RpgTheme.TEXT);var geometry=PlayerUiLayout.characterCard(cw,nameLines,metaLines);int my=y+geometry.metadataTop();pane.wrapped(PlayerUiModel.raceLabel(PlayerUiModel.race(d))+" · "+PlayerUiModel.clazz(d),cx+10,my,cw-20,RpgTheme.TEXT);my=y+geometry.profileTop();pane.label(HubState.profileName(text(d,"profile")),cx+10,my,cw-20,RpgTheme.MUTED);int by=y+height-(cw<350?2*ah+16:ah+10),bw=cw<350?cw-20:(cw-26)/2;String id=text(d,"id");var primary=add("open:"+id,new RpgButton(cx+10,by,bw,ah,PlayerUiModel.primary(d),"",()->open(id)).primary(true).wrappedTitle().hint(PlayerUiModel.description(d)+"\n"+(PlayerUiModel.creator(d)?PlayerUiModel.primary(d):PlayerUiModel.primaryReason(d))));primary.active=fresh&&!busy&&(PlayerUiModel.complete(d)?PlayerUiModel.sheet(d):PlayerUiModel.creator(d));var manage=add("manage:"+id,new RpgButton(cw<350?cx+10:cx+16+bw,cw<350?by+ah+6:by,bw,ah,"Manage Character","",()->{if(fresh&&!busy){selected=id;client.setScreen(new LibraryCharacterScreen(this,id));}}).wrappedTitle().hint("Edit, duplicate, submit or delete "+text(d,"name")));manage.active=fresh&&!busy;index++;if(index%columns==0)y+=rowHeight+10;}
  if(index%columns!=0)y+=rowHeight+10;if(QuickPanelLayout.pagination(page,more)){int bw=(w-6)/2;var prev=add("previous",new RpgButton(x,y+8,bw,22,"‹ Previous","",()->changePage(-1)).hint(page>0?"Return to the previous page":"You are on the first page"));prev.active=fresh&&!busy&&page>0;var next=add("next",new RpgButton(x+bw+6,y+8,bw,22,"Next ›","",()->changePage(1)).hint(more?"Browse more personal characters":"No further characters"));next.active=fresh&&!busy&&more;}pane.position(offset);if(!focus.isEmpty()){pane.focus(focus);setInitialFocus(pane);}}
 private RpgButton add(String key,RpgButton button){actions.add(button);if(!fresh||busy){button.active=false;button.hint("Load your library with Refresh before using this action.");}return pane.control(key,button);}
 private void changePage(int delta){if(busy||!fresh||delta<0&&page==0||delta>0&&!more)return;page+=delta;if(pane!=null)pane.position(0);refresh();}
 private void open(String id){if(!fresh||busy)return;selected=id;read(LIBRARY_GET,args("character",id),d->{var snapshot=DraftReplies.snapshot(d,id);client.setScreen(PlayerUiModel.complete(snapshot)?PlayerNavigation.sheet(this,new DashboardSource(true,id)):new CharacterWizardScreen(this,snapshot));});}
 @Override protected void request(dev.tacticalcombat.uiapi.UiApiService.Operation op,JsonObject a,java.util.function.Consumer<dev.tacticalcombat.uiapi.UiApiService.Reply> result){super.request(op,a,r->{result.accept(r);if(!r.code().equals("OK")){if(r.code().equals("FORBIDDEN")||r.code().equals("UNAVAILABLE"))records=List.of();build();}});}
 @Override public void tick(){super.tick();if(refreshButton!=null)refreshButton.active=!busy&&dev.tacticalcombat.client.ClientUiApi.supported();for(var b:actions)if(busy||!fresh)b.active=false;}
}
